mapper.select:
SELECT e.id,e.kind,e.namespace,e.external_id,e.current_version,v.checksum,v.payload FROM content_entity e JOIN content_version v ON
v.entity_id=e.id AND v.version=e.current_version WHERE e.namespace=#{namespace} AND
e.kind=#{kind} AND e.external_id=#{externalId}

SELECT e.id,e.kind,e.namespace,e.external_id,e.current_version,v.title,v.payload,v.status,v.version FROM content_entity e JOIN content_version v ON v.entity_id=e.id
AND v.version=(SELECT max(x.version) FROM content_version x WHERE x.entity_id=e.id AND x.status='PUBLISHED')
AND v.version=e.current_version
e.kind=#{kind}
ORDER BY e.idv.created_at ASCDESC, e.id ASC LIMIT #{query.size} OFFSET #{query.offset}
